&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Kagent&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Via Envoy&lt;/td&gt;
&lt;td&gt;✅&lt;/td&gt;
&lt;td&gt;Planned&lt;/td&gt;
